update_rule.pseudocode:
if t == 0:
  N = population_size
  if network_type == 0:
    build Erdos-Renyi with p = avg_degree / (N-1)
  elif network_type == 1:
    build Barabasi-Albert with m = preferential_attachment_m
  elif network_type == 2:
    build Watts-Strogatz with k = round(avg_degree), beta = rewiring_prob
  assign community_count groups using modularity-based or planted partition with assortativity_by_group and clustering_bias targets
  set edge_weights ~ Uniform(0.8,1.2)
  output graph.network and graph.groups

for each day t:
  if campaign_gaussian:
    mu = (campaign_start_day + campaign_end_day) / 2
    sigma = shape_sigma_days
    campaign = campaign_peak_intensity * exp(-0.5 * ((t - mu)/sigma)^2) if campaign_start_day <= t <= campaign_end_day else 0
  else:
    if t < campaign_start_day or t > campaign_end_day: campaign = 0
    else:
      len = campaign_end_day - campaign_start_day + 1
      mid = campaign_start_day + floor(len/2)
      if t <= mid:
        campaign = campaign_peak_intensity * (t - campaign_start_day) / max(1, mid - campaign_start_day)
      else:
        campaign = campaign_peak_intensity * (campaign_end_day - t) / max(1, campaign_end_day - mid)
  signal = clamp(baseline_media_signal + campaign - counter_misinformation_intensity, 0, max_media_reach_fraction)
  # policy nudges select a Bernoulli subset of non-adopters
  nudge_targets = sample_non_adopters_with_prob(policy_nudging_probability)
  output media.signal_t = signal and policy.nudge_targets = nudge_targets
